{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Restore the **25% / AUD 6 million cap**"
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "**AUD 5,000 de minimis**, and **AUD 50,000 tipping basket** (recovery from the first dollar once exceeded)."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Retain **24 months** for general claims."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Fundamental/title claims need a **separate 100% cap and at least six years**, free of the general basket, de minimis and knowledge bar."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Carve **fraud, wilful concealment and deliberate misconduct** out of all caps, baskets, time limits, exclusive remedies and non-reliance to the maximum extent enforceable."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Delete blanket data-room, accounts, register and public-record deemed disclosure."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete the blanket buyer/adviser knowledge and “discoverable” exclusions."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Make **effective consent and evidence that its conditions are satisfied** a pre-Completion requirement."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Obtain a **current payout figure**, repay the facility directly from Completion funds, and obtain **effective security releases** at Completion."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Separately show the DD-005 conditional **AUD 420,000 bonuses and any triggered on-costs** in the funds flow or have the Seller fund them"
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Broaden the indemnity beyond the narrow SOW3 payment claim to cover the resulting ownership, assignment, use and remediation exposure"
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Require preservation of logs and evidence, prompt investigation, regular updates and an agreed process for any remediation or notification shown to be necessary."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "Do not automatically treat AUD 330,000 as Debt or deduct it from price; equally, the Seller has not substantiated “ordinary course.”"
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Reject the attempt to apply general limits, exclusive remedy and non-reliance provisions to every claim."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Require independent evidence of ownership, absence or release of encumbrances, and Seller authority and capacity before Completion."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "tax and IP terms remain **open**, not settled or assumed unlimited."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

